--
-- Name: v_dashboard; Type: VIEW; Schema: retention; Owner: postgres
--

CREATE VIEW retention.v_dashboard AS
 SELECT ( SELECT count(*) AS count
           FROM retention.outbox) AS outbox_total,
    ( SELECT count(*) AS count
           FROM retention.outbox
          WHERE ((outbox.sent_at IS NULL) AND (outbox.error IS NULL))) AS outbox_pending,
    ( SELECT count(*) AS count
           FROM retention.outbox
          WHERE (outbox.sent_at IS NOT NULL)) AS outbox_sent_all,
    ( SELECT count(*) AS count
           FROM retention.outbox
          WHERE ((outbox.sent_at)::date = (now())::date)) AS outbox_sent_today,
    ( SELECT count(*) AS count
           FROM retention.outbox
          WHERE (outbox.error IS NOT NULL)) AS outbox_errors,
    ( SELECT count(*) AS count
           FROM retention.outbox
          WHERE (outbox.error ~~* '%403%blocked%'::text)) AS outbox_blocked_403,
    ( SELECT count(*) AS count
           FROM retention.dnd) AS dnd_total,
    ( SELECT count(*) AS count
           FROM retention.dnd
          WHERE (dnd.reason = 'tg_blocked_403'::text)) AS dnd_blocked_403;


ALTER VIEW retention.v_dashboard OWNER TO postgres;

--
-- Name: v_dnd_summary; Type: VIEW; Schema: retention; Owner: postgres
--

CREATE VIEW retention.v_dnd_summary AS
 SELECT count(*) AS dnd_total,
    count(*) FILTER (WHERE (reason = 'tg_blocked_403'::text)) AS dnd_blocked_403
   FROM retention.dnd;


ALTER VIEW retention.v_dnd_summary OWNER TO postgres;

--
-- Name: v_last_errors; Type: VIEW; Schema: retention; Owner: postgres
--

CREATE VIEW retention.v_last_errors AS
 SELECT id,
    user_id,
    template_key,
    scheduled_at,
    sent_at,
    "left"(error, 300) AS error
   FROM retention.outbox
  WHERE (error IS NOT NULL)
  ORDER BY id DESC
 LIMIT 100;


ALTER VIEW retention.v_last_errors OWNER TO postgres;

--
-- Name: v_template_summary; Type: VIEW; Schema: retention; Owner: postgres
--

CREATE VIEW retention.v_template_summary AS
 SELECT template_key,
    count(*) AS total,
    count(*) FILTER (WHERE ((sent_at IS NULL) AND (error IS NULL))) AS pending,
    count(*) FILTER (WHERE (sent_at IS NOT NULL)) AS sent_all,
    count(*) FILTER (WHERE ((sent_at)::date = (now())::date)) AS sent_today,
    count(*) FILTER (WHERE (error IS NOT NULL)) AS errors_all,
    count(*) FILTER (WHERE (error ~~* '%403%blocked%'::text)) AS blocked_403
   FROM retention.outbox
  GROUP BY template_key
  ORDER BY template_key;


ALTER VIEW retention.v_template_summary OWNER TO postgres;

